package com.fandazi.feature.cart;
import com.fandazi.feature.DomainException; import com.fandazi.feature.auth.UserRepository; import com.fandazi.feature.catalog.*; import java.math.BigDecimal; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CartService { private final CartDraftRepository drafts; private final MerchantRepository merchants; private final DishRepository dishes; private final UserRepository users; public CartService(CartDraftRepository drafts,MerchantRepository merchants,DishRepository dishes,UserRepository users){this.drafts=drafts;this.merchants=merchants;this.dishes=dishes;this.users=users;} @Transactional public CartDraft createDraft(Long userId,Long merchantId){var user=users.findById(userId).orElseThrow(()->new DomainException("用户不存在"));var merchant=merchants.findById(merchantId).orElseThrow(()->new DomainException("商家不存在"));return drafts.save(new CartDraft(user,merchant));} @Transactional public CartDraft replaceItems(Long userId,Long draftId,List<CartItemCommand> commands){var draft=owned(userId,draftId);if(commands==null||commands.isEmpty())throw new DomainException("购物车不能为空");List<CartDraftItem> items=new ArrayList<>();for(var c:commands){if(c.quantity()<=0)throw new DomainException("数量无效");var dish=dishes.findById(c.dishId()).orElseThrow(()->new DomainException("菜品不存在"));if(!dish.getMerchant().getId().equals(draft.getMerchant().getId()))throw new DomainException("菜品不属于商家");items.add(new CartDraftItem(draft,dish,c.quantity()));}draft.replaceItems(items);return draft;} @Transactional(readOnly=true) public CartQuote validate(Long userId,Long draftId){var draft=owned(userId,draftId);if(!draft.getMerchant().isOpen())throw new DomainException("商家未营业");List<CartQuote.Line> lines=new ArrayList<>();BigDecimal subtotal=BigDecimal.ZERO;for(var item:draft.getItems()){var dish=dishes.findById(item.getDish().getId()).orElseThrow(()->new DomainException("菜品不存在"));if(!dish.isListed())throw new DomainException("菜品已下架");if(dish.getStock()<item.getQuantity())throw new DomainException("库存不足");BigDecimal total=dish.getPrice().multiply(BigDecimal.valueOf(item.getQuantity()));subtotal=subtotal.add(total);lines.add(new CartQuote.Line(dish.getId(),dish.getName(),item.getQuantity(),dish.getPrice(),total));}if(subtotal.compareTo(draft.getMerchant().getMinimumOrder())<0)throw new DomainException("未达到起送价");BigDecimal fee=draft.getMerchant().getDeliveryFee();return new CartQuote(draft.getMerchant().getId(),List.copyOf(lines),subtotal,fee,BigDecimal.ZERO,subtotal.add(fee));} public CartDraft owned(Long userId,Long id){return drafts.findByIdAndUserId(id,userId).orElseThrow(()->new DomainException("购物车不存在"));} }
